<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Throwable; use Pterodactyl\Models\Server; use Pterodactyl\Models\Database; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Symfony\Component\HttpFoundation\StreamedResponse; use Pterodactyl\Services\Dezerx\Databases\DatabaseTransfer; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\DatabaseExportRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\DatabaseImportRequest; class DatabaseTransferController extends ClientApiController { public function __construct(private readonly DatabaseTransfer $transfer) { parent::__construct(); } public function summary(DatabaseExportRequest $request, Server $server, Database $database): JsonResponse { return new JsonResponse([ 'tables' => $this->transfer->tables($database), 'size' => $this->transfer->size($database), 'maxUploadKb' => DatabaseTransfer::MAX_UPLOAD_KB, ]); } public function export(DatabaseExportRequest $request, Server $server, Database $database): StreamedResponse { $filename = $this->transfer->filename($database); Activity::event('server:database.export') ->subject($database) ->property('name', $database->database) ->log(); return new StreamedResponse(function () use ($database) { $handle = fopen('php://output', 'wb'); foreach ($this->transfer->export($database) as $chunk) { fwrite($handle, $chunk); flush(); } fclose($handle); }, 200, [ 'Content-Type' => 'application/sql', 'Content-Disposition' => 'attachment; filename="' . $filename . '"', 'X-Accel-Buffering' => 'no', ]); } public function import(DatabaseImportRequest $request, Server $server, Database $database): JsonResponse { $request->validate([ 'file' => ['required', 'file', 'max:' . DatabaseTransfer::MAX_UPLOAD_KB], 'wipe' => ['sometimes', 'boolean'], ]); $path = $request->file('file')->getRealPath(); $sql = $path === false ? false : file_get_contents($path); if ($sql === false) { return new JsonResponse(['errors' => [[ 'code' => 'UnreadableUpload', 'detail' => 'That file could not be read.', ]]], 422); } try { $dropped = $request->boolean('wipe') ? $this->transfer->wipe($database) : 0; $result = $this->transfer->import($database, $sql); } catch (Throwable $exception) { return new JsonResponse(['errors' => [[ 'code' => 'ImportFailed', 'detail' => 'The database could not be reached: ' . $exception->getMessage(), ]]], 502); } Activity::event('server:database.import') ->subject($database) ->property([ 'name' => $database->database, 'statements' => $result['statements'], 'wiped' => $dropped, ]) ->log(); return new JsonResponse([ 'statements' => $result['statements'], 'dropped' => $dropped, 'failed' => $result['failed'], ]); } } 